def E(epsilon):
    x = 0.5 + epsilon
    y = 0.5 - epsilon
    # E(x, y, 0, 0) = y / (16x^3 + 1) + x
    term1 = y / (16 * x**3 + 1)
    return term1 + x

epsilon_values = [0, 0.01, 0.05, 0.1]
results = {}
for eps in epsilon_values:
    results[eps] = E(eps)

for eps, value in results.items():
    print(f"E(epsilon={eps}) = {value}")
